#!/usr/bin/env python3
"""Writes threads_naive.caspien and threads_opt.caspien (64 `par` handles per wave cannot sit in an array: the handle type has no name)."""
import os
WAVE = 64
HERE = os.path.dirname(os.path.abspath(__file__))

HEAD = """// threads: spawn many OS threads, each runs the same integer kernel on its own state, collect every result. No data is shared
// between the threads. Tasks run in waves of 64 `par` threads; N comes from THREADS_N and must be a multiple of 64.
// Generated by gen.py: a `par` handle has no type name, so it cannot be stored in an array and the 64 handles of a wave are
// 64 named locals, each polled through its `state` and read with `resolve()`.
%s
import "../../../stdlib/libc.caspien"
import "../../../stdlib/gt_init.caspien"
import "../../../stdlib/gt_register.caspien"
import "../../../stdlib/gt_alive_check.caspien"
import "../../../stdlib/gt_destruct.caspien"
import "../../../stdlib/gt_moved.caspien"
import "../../../stdlib/par_call.caspien"
import "../../../stdlib/await_call.caspien"
extern getenv(static imut string) static imut string
extern atol(static imut string) mut u64
"""

NAIVE_TASK = """
// One xorshift64 step, as a function.
func step(s: mut u64) mut u64{
	let a = mut bits_xor(s, bits_left(s, 13))
	let b = mut bits_xor(a, bits_right(a, 7))
	return bits_xor(b, bits_left(b, 17))
}

@async
func task(id: mut u64) mut u64{
	let s = mut ((id + 1) * 2654435761)
	let acc = mut 0
	for i in 0..1000000{
		s = step(s)
		acc += bits_and(s, 255)
	}
	return acc
}
"""

OPT_TASK = """
@async
func task(id: mut u64) mut u64{
	let s = mut ((id + 1) * 2654435761)
	let acc = mut 0
	for i in 0..250000{                  // the kernel is unrolled four times, everything stays in registers
		s = bits_xor(s, bits_left(s, 13))
		s = bits_xor(s, bits_right(s, 7))
		s = bits_xor(s, bits_left(s, 17))
		acc += bits_and(s, 255)
		s = bits_xor(s, bits_left(s, 13))
		s = bits_xor(s, bits_right(s, 7))
		s = bits_xor(s, bits_left(s, 17))
		acc += bits_and(s, 255)
		s = bits_xor(s, bits_left(s, 13))
		s = bits_xor(s, bits_right(s, 7))
		s = bits_xor(s, bits_left(s, 17))
		acc += bits_and(s, 255)
		s = bits_xor(s, bits_left(s, 13))
		s = bits_xor(s, bits_right(s, 7))
		s = bits_xor(s, bits_left(s, 17))
		acc += bits_and(s, 255)
	}
	return acc
}
"""

def main_fn():
    L = ["", "func main() void{", "\t?catch(e){", "\t\tunsafe extern{ printf(\"FAIL %s\\n\", e) }", "\t\treturn", "\t}",
         "\tlet n = mut 0", "\tunsafe extern{ n = atol(getenv(\"THREADS_N\")) }", "\tlet total = mut 0", "\tlet waves = mut (n / %d)" % WAVE,
         "\tfor wave in 0..waves{", "\t\tlet base = mut (wave * %d)" % WAVE]
    for j in range(WAVE):
        L.append("\t\tlet h%d = mut ? par task(mut (base + %d))" % (j, j))
    for j in range(WAVE):
        L += ["\t\tfor w in 0..100000000{",
              "\t\t\tlet ready = mut false",
              "\t\t\tmatch h%d.state{" % j,
              "\t\t\t\tREADY:{ ready = true }",
              "\t\t\t\tdefault:{ ready = false }",
              "\t\t\t}",
              "\t\t\tif ready{ break }",
              "\t\t\tyield",
              "\t\t}",
              "\t\ttotal += h%d.resolve(h%d)" % (j, j)]
    L += ["\t}", "\tunsafe extern{ printf(\"tasks=%llu checksum=%llu\\n\", n, total) }", "}", ""]
    return "\n".join(L)

for name, task, desc in (("threads_naive", NAIVE_TASK, "naive: the kernel step is a function"),
                         ("threads_opt", OPT_TASK, "optimized: the kernel is inlined by hand and unrolled four times")):
    open(os.path.join(HERE, name + ".caspien"), "w").write(HEAD % ("// " + desc) + task + main_fn())
